#!/system/bin/sh
# wp210 probe kit: shared functions (read-only). Sourced by the boot scripts.
# Reads the DVFSRC/SPM registers through MediaTek's DVFSRC debug driver (kprobes)
# and records MediaTek SIP secure calls. Output: /data/local/tmp/wp210-probe/<boot id>/
T=/sys/kernel/tracing
W=/data/adb/wp210
BASE=/data/local/tmp/wp210-probe
BID=$(cut -c1-8 /proc/sys/kernel/random/boot_id)
D=$BASE/$BID
FN=mtk_dvfsrc_helper:dvfsrc_dump_reg
mkdir -p $D; chmod 755 $BASE $D
up() { cut -d' ' -f1 /proc/uptime; }
note() { echo "$(up) $*" >> $D/events.txt; chmod 644 $D/events.txt; }
helper() { for f in /sys/devices/platform/soc/*dvfsrc*/*dvfsrc-helper/dvfsrc_dump /sys/devices/platform/*dvfsrc*/*dvfsrc-helper/dvfsrc_dump; do [ -e "$f" ] && { echo "$f"; return 0; }; done; return 1; }
rate() { for f in /sys/bus/platform/drivers/*/dram_data_rate; do [ -e "$f" ] && { cat "$f" 2>/dev/null | tr -d '\n' | sed 's/DRAM data rate = //'; return; }; done; echo none; }
susp() { cat /sys/power/suspend_stats/success 2>/dev/null || echo ?; }
screen() { for f in /sys/class/leds/lcd-backlight/brightness /sys/class/backlight/*/brightness; do [ -e "$f" ] && { cat "$f"; return; }; done; echo ?; }
lock() { n=0; while ! mkdir $D/.lock 2>/dev/null; do sleep 0.2; n=$((n+1)); [ $n -gt 150 ] && rmdir $D/.lock; done; }
unlock() { rmdir $D/.lock 2>/dev/null; }
inst() { [ -d $T/instances/$1 ] || mkdir $T/instances/$1; }
# probe NAME "ARGS": one kprobe on the debug driver's dump, one dump, prints the values
probe() {
  H=$(helper) || return 1
  inst wp210r
  echo "p:wp210/$1 $FN $2" >> $T/kprobe_events 2>/dev/null || { note "probe $1 refused: $(tail -1 $T/error_log)"; return 1; }
  echo > $T/instances/wp210r/trace
  echo 1 > $T/instances/wp210r/events/wp210/$1/enable
  cat "$H" > /dev/null
  echo 0 > $T/instances/wp210r/events/wp210/$1/enable
  grep " $1: " $T/instances/wp210r/trace | head -1 | sed 's/.*) //'
  echo "-:wp210/$1" >> $T/kprobe_events
}
# which struct word is the DVFSRC and which the SPM (static registers: DVFSRC 0x290, SPM 0x0)
ptrs() {
  [ -s $D/ptr ] && { cat $D/ptr; return 0; }
  lock; [ -s $D/ptr ] && { unlock; cat $D/ptr; return 0; }
  V=$(probe chk "a0=+0x0(+32(%x0)):x32 a290=+0x290(+32(%x0)):x32 b0=+0x0(+40(%x0)):x32 b290=+0x290(+40(%x0)):x32 a194=+0x194(+32(%x0)):x32 b194=+0x194(+40(%x0)):x32") || { unlock; return 1; }
  case "$V" in
    *a290=0x60400020*b0=0x1\ *) echo "32 40" > $D/ptr ;;
    *a0=0x1\ *b290=0x60400020*) echo "40 32" > $D/ptr ;;
    *) unlock; note "pointers not recognised: $V"; return 1 ;;
  esac
  unlock
  note "pointers (dvfsrc spm): $(cat $D/ptr) from $V"; cat $D/ptr
}
# one line of key registers -> summary.txt
key() {
  P=$(ptrs) || return 1; DV=${P% *}; SP=${P#* }
  lock
  V=$(probe key "pc=+0x194(+$SP(%x0)):x32 scu1=+0x104(+$SP(%x0)):x32 flag0=+0x600(+$SP(%x0)):x32 spmi=+0x308(+$SP(%x0)):x32 ev=+0x380(+$SP(%x0)):x32 dsta=+0x388(+$SP(%x0)):x32 lv1=+0x38c(+$SP(%x0)):x32 lv2=+0x390(+$SP(%x0)):x32 opp=+0x394(+$SP(%x0)):x32 cmd0=+0x310(+$SP(%x0)):x32 ctl=+0x0(+$DV(%x0)):x32 swreq=+0x18(+$DV(%x0)):x32 dbg0=+0x29c(+$DV(%x0)):x32 last=+0x3ac(+$DV(%x0)):x32 r5c8=+0x5c8(+$DV(%x0)):x32 level=+0x5f0(+$DV(%x0)):x32")
  unlock
  echo "$(up) [$REASON] rate=$(rate) susp=$(susp) screen=$(screen) $V" >> $D/summary.txt; chmod 644 $D/summary.txt
}
# full dump: the driver's own dump, the DVFSRC page, all 416 SPM registers of k6895_spm_reg.h
