# continuous record of SIP secure calls (x0 0x82xxxxxx / 0xc2xxxxxx) -> smc.txt
smc_start() {
  [ -s $D/smc.pid ] && kill -0 $(cat $D/smc.pid) 2>/dev/null && return 0
  inst wp210s
  [ -d $T/events/wp210/smc ] || echo "p:wp210/smc __arm_smccc_smc a0=%x0:x64 a1=%x1:x64 a2=%x2:x64 a3=%x3:x64 a4=%x4:x64" >> $T/kprobe_events || { note "smc probe refused: $(tail -1 $T/error_log)"; return 1; }
  echo 16384 > $T/instances/wp210s/buffer_size_kb
  echo '(a0 >= 0x82000000 && a0 < 0x83000000) || (a0 >= 0xc2000000 && a0 < 0xc3000000)' > $T/instances/wp210s/events/wp210/smc/filter
  echo 1 > $T/instances/wp210s/events/wp210/smc/enable
  touch $D/smc.txt; chmod 644 $D/smc.txt
  nohup sh -c "cat $T/instances/wp210s/trace_pipe >> $D/smc.txt" > /dev/null 2>&1 &
  echo $! > $D/smc.pid
  note "smc recording started (pid $(cat $D/smc.pid))"
}
smc_stop() {
  [ -s $D/smc.pid ] && kill $(cat $D/smc.pid) 2>/dev/null
  echo 0 > $T/instances/wp210s/events/wp210/smc/enable 2>/dev/null
  echo "-:wp210/smc" >> $T/kprobe_events 2>/dev/null
  rm -f $D/smc.pid; note "smc recording stopped"
}
